package br.com.onda;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.function.Consumer;
/** One catalogue request per explicit search. No logo downloads, polling or station probes. */
final class RadioDirectory {
 static List<RadioStation> search(String term,boolean brazil,Consumer<HttpURLConnection> active)throws Exception{String query=term==null?"":term.trim();if(query.length()>120)throw new IOException("Use até 120 caracteres na busca.");Exception last=null;for(String host:new String[]{"de1.api.radio-browser.info","nl1.api.radio-browser.info"}){if(Thread.currentThread().isInterrupted())throw new InterruptedException();HttpURLConnection c=null;try{String url="https://"+host+"/json/stations/search?hidebroken=true&order=clickcount&reverse=true&limit=100"+(brazil?"&countrycode=BR":"")+(query.isEmpty()?"":"&name="+URLEncoder.encode(query,"UTF-8"));c=(HttpURLConnection)new URL(url).openConnection();active.accept(c);c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("User-Agent","Onda/0.66.0 (Android radio player)");c.setRequestProperty("Accept","application/json");if(c.getResponseCode()!=200)throw new IOException("Catálogo indisponível agora.");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedException();if(out.size()+n>2*1024*1024)throw new IOException("Resposta do catálogo muito grande.");out.write(b,0,n);}return RadioStation.read(out.toString(StandardCharsets.UTF_8.name()),true);}}catch(InterruptedException stop){throw stop;}catch(Exception e){last=e;}finally{if(c!=null)c.disconnect();}}throw new IOException("Não foi possível consultar as rádios. Tente novamente ou abra suas favoritas.",last);}
}
